-- 22 novembre 2026 : 12 dispositifs ciblés, sources Région / Département.
-- Une source officielle confirmée ne valide ni un barème, ni une ouverture de session, ni l'éligibilité.
-- Distinguer appel prestataires (Numérisak), aide aux citoyens et dispositif via établissement.
DO $aides_20261122$
DECLARE r record;
BEGIN
 PERFORM pg_advisory_xact_lock(84690123);
 LOCK TABLE public.aides_reunion IN SHARE ROW EXCLUSIVE MODE;
 PERFORM setval(pg_get_serial_sequence('public.aides_reunion','id'), GREATEST((SELECT COALESCE(MAX(id),1) FROM public.aides_reunion),(SELECT last_value FROM public.aides_reunion_id_seq)), true);
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"nom":"Pass Culture régional — lycéens et apprentis 2026","categorie":"jeunesse","organisme":"Région Réunion","type_dispositif":"credit_culturel","zone_couverte":"La Réunion (établissements participants)","source":"https://www.regionreunion.com/aides/pass-culture-lyceens-et-apprentis/","period":"Dispositif régional présenté en juin 2026, mis à jour en août 2026. Activités et bénéficiaires via les établissements.","description":"Dispositif régional distinct du Pass Culture national, destiné aux lycéens et apprentis pour des sorties et événements culturels via les établissements participants. Ce n''est pas de l''argent versé aux jeunes.","demarches":"Se renseigner auprès du lycée ou du centre de formation sur la participation de l''établissement et les sorties proposées.","statut":"source_confirmee","prio":92},{"nom":"Numérisak 2026-2027 — cartable numérique des lycéens","categorie":"jeunesse","organisme":"Région Réunion","type_dispositif":"aide_materielle","zone_couverte":"La Réunion (lycéens éligibles)","source":"https://www.regionreunion.com/appel-a-projets/appel-a-candidature-le-cartable-numerique-numerisak-volet-equipement-2026-2027/","period":"Programme d''équipement 2026-2027 documenté ; procédure et critères propres aux élèves à confirmer auprès du lycée et de la Région.","description":"Le programme régional Numérisak 2026-2027 porte sur l''équipement informatique des lycéens, selon conditions de la campagne. La page consultée est un appel à candidature destiné aux vendeurs partenaires, pas un formulaire de demande pour les familles.","demarches":"Demander au lycée et à la Région le parcours de demande pour les élèves, les justificatifs et les règles de la rentrée 2026-2027 ; ne pas remplir l''appel destiné aux vendeurs.","statut":"a_reconfirmer","prio":91},{"nom":"Un trimestre, un livre 2026-2027 — Région Réunion","categorie":"jeunesse","organisme":"Région Réunion","type_dispositif":"aide_materielle","zone_couverte":"La Réunion (lycées participants)","source":"https://www.regionreunion.com/aides/un-trimestre-un-livre/","period":"Année scolaire 2026-2027 ; modalités d''établissement et de remise à vérifier.","description":"Dispositif régional d''accès aux livres destiné aux lycéens pour l''année scolaire 2026-2027. Les conditions sont organisées avec les établissements. Ne pas présenter comme une allocation monétaire.","demarches":"Demander au lycée ou au référent ARTICE le formulaire régional 2026-2027 et les règles d''utilisation.","statut":"source_confirmee","prio":90},{"nom":"Aide ménagère légale — Département Réunion","categorie":"senior","organisme":"Département de La Réunion","type_dispositif":"accompagnement","zone_couverte":"La Réunion","source":"https://www.departement974.fr/aide/aide-laide-menagere-legale","period":"Page départementale consultée en novembre 2026 ; critères de ressources et d''autonomie à confirmer au service social.","description":"Aide légale à domicile, notamment pour certaines personnes âgées qui ont besoin d''aide pour des travaux ménagers et le maintien à domicile, sous conditions. Elle finance un service et non une allocation librement utilisable.","demarches":"Contacter le CCAS ou les services de l''aide sociale aux adultes du Département pour l''évaluation et le dossier.","statut":"source_confirmee","prio":90},{"nom":"Aide ménagère facultative — Département Réunion","categorie":"senior","organisme":"Département de La Réunion","type_dispositif":"accompagnement","zone_couverte":"La Réunion","source":"https://www.departement974.fr/aide/aide-laide-menagere-facultative","period":"Page départementale consultée en novembre 2026 ; conditions et financement à confirmer.","description":"Soutien facultatif du Département permettant le financement d''heures de services ménagers pour des personnes âgées ou répondant à d''autres situations prévues par le règlement. Pas un versement libre en espèces.","demarches":"Se renseigner auprès du service social départemental ou du CCAS sur l''évaluation, les règles et le dépôt de dossier.","statut":"source_confirmee","prio":89},{"nom":"APA en établissement — Département de La Réunion","categorie":"senior","organisme":"Département de La Réunion","type_dispositif":"aide_financiere","zone_couverte":"La Réunion","source":"https://www.departement974.fr/aide/aide-l-apa-allocation-personnalisee-dautonomie-en-etablissement","period":"Page officielle de l''APA en établissement consultée en novembre 2026 ; décision après évaluation, calcul selon situation.","description":"Allocation personnalisée d''autonomie pour une personne âgée d''au moins 60 ans en établissement et présentant une perte d''autonomie reconnue. Le montant dépend de l''évaluation et de la participation éventuelle ; aucune somme uniforme.","demarches":"Demander le dossier APA aux services de l''aide sociale aux adultes du Département ou au CCAS ; faire évaluer la perte d''autonomie et joindre les pièces nécessaires.","statut":"source_confirmee","prio":88},{"nom":"Carte mobilité inclusion (CMI) — Département de La Réunion","categorie":"handicap","organisme":"Département de La Réunion","type_dispositif":"service_gratuit","zone_couverte":"La Réunion","source":"https://departement974.fr/aide/aide-carte-mobilite-inclusion-cmi","period":"Fiche du Département consultée en novembre 2026 ; conditions liées au handicap et/ou à la perte d''autonomie.","description":"Carte mobilité inclusion pouvant ouvrir, selon la mention accordée, des droits à la priorité, au stationnement ou à des avantages spécifiques. Ce n''est pas une allocation en argent.","demarches":"Vérifier les conditions et déposer la demande par la MDPH ou le circuit départemental indiqué selon la situation ; ne pas supposer une attribution automatique.","statut":"source_confirmee","prio":90},{"nom":"Aide à l''amélioration de l''habitat — Département Réunion","categorie":"logement","organisme":"Département de La Réunion","type_dispositif":"aide_financiere","zone_couverte":"La Réunion","source":"https://www.departement974.fr/aide/aide-habitat-logement-amelioration-de-lhabitat","period":"Règlement départemental du 14 novembre 2024 cité par la page ; barèmes 2025 affichés, à ne pas considérer comme barèmes 2026.","description":"Soutien départemental aux travaux d''amélioration et d''adaptation d''un logement principal occupé par un ménage répondant aux conditions, notamment personnes âgées, handicapées et accueillants familiaux. La page contient des plafonds 2025 et une liste d''opérateurs qui peut être obsolète ; ne pas recommander SOLIHA Réunion sans vérifier son statut.","demarches":"Contacter la Direction de l''habitat du Département, demander le règlement et le barème actuels, vérifier la liste d''opérateurs actuellement agréés et le dossier à déposer.","statut":"a_reconfirmer","prio":92},{"nom":"RSO — régularisation du statut d''occupation et sortie de l''indivision","categorie":"logement","organisme":"Département de La Réunion","type_dispositif":"aide_financiere","zone_couverte":"La Réunion","source":"https://www.departement974.fr/aide/aide-habitat-logement-rso-regularisation-statut-doccupation-sortie-de-lindivision","period":"Programme décrit sur le site du Département ; critères et montants de l''exercice 2026 à reconfirmer.","description":"Aide départementale relative à la régularisation du statut d''occupation d''un logement et à la sortie de l''indivision pour certains ménages, dans le cadre de projets d''habitat, sous conditions.","demarches":"Contacter la Direction de l''habitat du Département avant toute démarche notariale payante, afin de vérifier les conditions, les opérateurs et le dossier requis.","statut":"a_reconfirmer","prio":85},{"nom":"Pass Numérique — aide aux démarches en ligne à La Réunion","categorie":"administratif","organisme":"Région Réunion","type_dispositif":"accompagnement","zone_couverte":"La Réunion (structures partenaires selon implantation)","source":"https://www.regionreunion.com/liens-utiles/article/liens-utiles/liens-utiles/article/liens-utiles/contact/article/contact/aides-services/article/le-pass-numerique-pour-se-familiariser-avec-les-demarches-en-ligne","period":"Dispositif initié en 2021 et encore évoqué par la Région en 2026 ; disponibilité des permanences en 2026-2027 à reconfirmer.","description":"Accompagnement annoncé gratuitement par la Région pour découvrir l''informatique et réaliser des démarches numériques, à travers des lieux partenaires. Ne pas garantir une session ouverte près de l''utilisateur.","demarches":"Consulter la page régionale et demander aux partenaires d''inclusion numérique de sa commune si des séances Pass Numérique sont proposées.","statut":"a_reconfirmer","prio":87},{"nom":"Cinéma — lycéens et apprentis en salle 2026","categorie":"jeunesse","organisme":"Région Réunion","type_dispositif":"credit_culturel","zone_couverte":"La Réunion (établissements participants)","source":"https://www.regionreunion.com/aides/audiovisuel-lyceens-et-apprentis-au-cinema/","period":"Fiche Région mise à jour en août 2026 ; dépend de l''adhésion de l''établissement.","description":"Action régionale d''éducation à l''image permettant aux lycéens et apprentis de découvrir des œuvres cinématographiques en salle dans un cadre organisé. Ce n''est pas une somme directement versée au jeune.","demarches":"Demander à l''établissement scolaire ou au CFA s''il participe au dispositif et quelles sorties sont organisées.","statut":"source_confirmee","prio":84},{"nom":"Fonds de garantie unifié de l''habitat social — FGUHR","categorie":"logement","organisme":"Département de La Réunion","type_dispositif":"orientation","zone_couverte":"La Réunion","source":"https://www.departement974.fr/aide/aide-habitat-logement-fonds-de-garantie-unifie-de-lhabitat-social-de-reunion-fguhr","period":"Page départementale consultée en novembre 2026 ; financement bancaire, éligibilité et mise en œuvre à confirmer.","description":"Fonds départemental de garantie destiné notamment à sécuriser certains prêts bancaires complémentaires liés à l''accession ou à l''amélioration de logements sociaux. Le dispositif ne correspond pas à un versement automatique au ménage.","demarches":"Se rapprocher du Département et du financeur bancaire pour vérifier si son projet d''habitat relève du fonds et les garanties effectivement disponibles.","statut":"a_reconfirmer","prio":77}]'::jsonb) AS x (
   nom text,categorie text,organisme text,type_dispositif text,zone_couverte text,
   source text,period text,description text,demarches text,statut text,prio integer
 )
 LOOP
 IF NOT EXISTS (SELECT 1 FROM public.aides_reunion a WHERE lower(btrim(a.nom))=lower(btrim(r.nom))) THEN
  INSERT INTO public.aides_reunion (nom,categorie,organisme,type_dispositif,zone_couverte,
    description,description_fr,description_kreol,demarches_fr,demarches_kreol,
    lien,lien_officiel,source_verification,date_verification,periode_validite,statut_verification,score_priorite,actif)
  VALUES (r.nom,r.categorie,r.organisme,r.type_dispositif,r.zone_couverte,
    r.description,r.description,'Dispozitif-la i existe dapre bann sources officielles. Vérifi condition, montant ek disponibilité avan demande.',
    r.demarches,'Kontakte organisme ousa établissement pou vérifi demars ek bann conditions.',
    r.source,r.source,r.source,DATE '2026-11-22',r.period,r.statut,r.prio,true);
 END IF;
 END LOOP;
END
$aides_20261122$;
SELECT count(*) AS total, count(*) FILTER(WHERE actif) AS actives, MAX(id) AS dernier_id FROM public.aides_reunion;